// Select ONE channel and enter a topic. Only enabled channel can run.
const selected_channel_id = "apex_reveal_studio";
const topic = "A futuristic electric grand tourer reveal";
const channels = [{"id":"apex_reveal_studio","name":"Apex Reveal Studio","enabled":true,"niche":"Premium cinematic automotive reveals and design showcases","style":"Photorealistic premium automotive cinematography, dramatic reveal pacing, refined camera moves, realistic materials and reflections, no fake badges or invented manufacturer claims.","structure":"Hook with a striking detail; reveal silhouette; exterior design sequence; interior or engineering detail; memorable final hero shot.","duration":"30-45 seconds","voice":"Concise energetic premium English narrator; 75-95 words maximum.","safety":"Do not invent specifications, prices, range, horsepower, release dates or brand claims. Flag unknown facts as VERIFY."},{"id":"brightboard_academy","name":"BrightBoard Academy","enabled":false,"niche":"Short educational explainers presented as clean whiteboard animation","style":"Minimal white background, hand-drawn black line illustrations, restrained accent colors, clear diagrams, readable labels, progressive visual explanation.","structure":"Curiosity question; simple definition; three visual teaching beats; quick example; one-sentence recap.","duration":"35-50 seconds","voice":"Friendly clear English teacher voice; 90-115 words maximum.","safety":"Use accurate age-appropriate explanations. Flag uncertain facts for verification."},{"id":"creature_set_stories","name":"Creature Set Stories","enabled":false,"niche":"Original creature concepts and fictional behind-the-scenes creature/VFX set stories","style":"Cinematic creature design, practical-effects workshop atmosphere, texture close-ups, scale references, believable production details; clearly label fictional concepts as imagined.","structure":"Creature hook; design reveal; three imagined build/effect details; creature in a scene; final reveal.","duration":"30-45 seconds","voice":"Wonder-filled documentary-style English narrator; 80-105 words maximum.","safety":"Never claim fictional creature builds or productions are real. Label invented production stories as fictional."},{"id":"built_through_time","name":"Built Through Time","enabled":false,"niche":"The history and evolution of companies, inventions, products and technologies","style":"Premium historical mini-documentary; archival-inspired visuals, timeline transitions, period-appropriate environments, clear dates and milestones.","structure":"Present-day hook; origin; key turning point; evolution through time; present-day impact.","duration":"40-55 seconds","voice":"Authoritative engaging English mini-documentary narrator; 100-130 words maximum.","safety":"Do not fabricate dates, founders, milestones or statistics. Flag factual claims requiring source verification."},{"id":"microdetail_garage","name":"MicroDetail Garage","enabled":false,"niche":"Miniature vehicle cleaning, restoration and detailing with satisfying ASMR","style":"Photorealistic macro miniature workshop, tiny tools, realistic water/foam/dirt physics, locked clean compositions, tactile close-ups, satisfying transformations.","structure":"Dirty miniature vehicle hook; foam and brush detail; rinse; precision drying/polish; pristine final reveal.","duration":"20-35 seconds","voice":"No spoken narration by default; prioritize natural ASMR sound. Optional one-line caption only.","safety":"Keep miniature scale visually consistent. No impossible transformations or inconsistent prop sizes."},{"id":"twistframe_stories","name":"TwistFrame Stories","enabled":false,"niche":"Original 2D stickman micro-stories with suspense, choices and unexpected endings","style":"Simple expressive 2D stickman animation, clean backgrounds, consistent character design, readable staging, strong visual storytelling.","structure":"Immediate problem; escalation in two beats; apparent solution; unexpected but logical twist; punchy ending.","duration":"30-45 seconds","voice":"Expressive conversational English storyteller; 80-110 words maximum.","safety":"Stories must be original. Keep character appearance, props and spatial continuity consistent."},{"id":"inside_the_line","name":"Inside the Line","enabled":false,"niche":"How everyday products are manufactured, assembled and quality-checked","style":"High-quality industrial documentary visuals, macro machinery details, clean factory environments, process-focused camera work, realistic materials and safety practices.","structure":"Finished product hook; raw materials; key production stages; quality control; finished product reveal.","duration":"40-55 seconds","voice":"Clear informative English documentary narrator; 100-130 words maximum.","safety":"Do not invent factory procedures, temperatures, speeds, company names or machine specifications. Flag claims for verification."}];
const chosen = channels.find(c => c.id === selected_channel_id);
if (!chosen) throw new Error("Unknown channel ID.");
if (!chosen.enabled) throw new Error("This channel is disabled. Enable it in the channel configuration only after the first test passes.");
if (!topic || topic.trim().length < 4) throw new Error("Enter a specific topic.");
return [{json:{channel_id:chosen.id,channel_name:chosen.name,topic:topic.trim(),profile:chosen,test_mode:true}}];
